#include <utility> // For std::pair

std::vector<std::pair<int, int>> generateSequence(int w, int h) {
    std::vector<std::pair<int, int>> sequence;

    for (int i = 0; i < w; ++i) { // Loop over width
        for (int j = 0; j < h; ++j) { // Loop over height
            sequence.push_back(std::make_pair(i, j)); // Add (i, j) to the sequence
        }
    }

    return sequence;
}

int main() {
