       "activeTab",
       "contextMenus",
       "clipboardWrite"
     ],
     "background": {
       "scripts": ["background.js"],
       "persistent": false
     },
     "content_scripts": [
       {
         "matches": ["<all_urls>"],
         "js": ["content.js"]
       }
     ],
     "browser_action": {
       "default_popup": "popup.html"
     }
   }
   ```

