Here's a utility class with methods to convert some common SQL queries to MongoDB queries:

```java
import com.mongodb.client.MongoCollection;
import org.bson.BsonDocument;
import org.bson.BsonInt32;
import org.bson.BsonString;
import org.bson.conversions.Bson;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

public class SqlToMongoQueryConverter {

    public static Bson convertWhereClause(String whereClause) {
        if (whereClause == null || whereClause.isEmpty()) {
            return new BsonDocument();
        }

        String[] conditions = whereClause.split(" AND ");
        List<Bson> filters = new ArrayList<>();

        for (String condition : conditions) {
            String[] parts = condition.split(" ");
            if (parts.length != 3) {
                throw new IllegalArgumentException("Invalid WHERE clause format: " + condition);
            }

            String field = parts[0];
            String operator = parts[1];
            String value = parts[2];

            switch (operator) {
                case "=":
                    filters.add(Filters.eq(field, new BsonString(value)));
                    break;
                case "!=":
                    filters.add(Filters.ne(field, new BsonString(value)));
                    break;
                case ">":
                    filters.add(Filters.gt(field, new BsonInt32(Integer.parseInt(value))));
                    break;
                case "<":
                    filters.add(Filters.lt(field, new BsonInt32(Integer.parseInt(value))));
                    break;
                case ">=":
                    filters.add(Filters.gte(field, new BsonInt32(Integer.parseInt(value))));
                    break;
                case "<=":
                    filters.add(Filters.lte(field, new BsonInt32(Integer.parseInt(value))));
                    break;
                case "LIKE":
                    filters.add(Filters.regex(field, Pattern.compile(value.replace("%", ".*"))));
                    break;
                default:
                    throw new IllegalArgumentException("Unsupported operator: " + operator);
            }
        }

        return Filters.and(filters);
    }

    public static Bson convertOrderByClause(String orderByClause) {
        if (orderByClause == null || orderByClause.isEmpty()) {
            return new BsonDocument();
        }

        String[] parts = orderByClause.split(" ");
        if (parts.length != 2) {
            throw new IllegalArgumentException("Invalid ORDER BY clause format: " + orderByClause);
        }

        String field = parts[0];
        String direction = parts[1];

        if ("ASC".equalsIgnoreCase(direction)) {
            return Sorts.ascending(field);
        } else if ("DESC".equalsIgnoreCase(direction)) {
            return Sorts.descending(field);
        } else {
            throw new IllegalArgumentException("Unsupported ORDER BY direction: " + direction);
        }
    }

    public static Bson convertLimitClause(int limit) {
        return Filters.limit(limit);
    }

    public static Bson convertOffsetClause(int offset) {
        return Filters.skip(offset);
    }

    public static <T> List<T> executeQuery(MongoCollection<T> collection, String whereClause, String orderByClause, int limit, int offset) {
        Bson whereFilter = convertWhereClause(whereClause);
