```javascript
function sortArray(input, arr) {
  // Filter the array into three categories: exact match, prefix, and substring
  const exactMatch = arr.filter(str => str === input);
  const prefix = arr.filter(str => str.startsWith(input) && str !== input);
  const substring = arr.filter(str => str.includes(input) && !str.startsWith(input));

  // Sort the prefix and substring arrays alphabetically
  prefix.sort();
  substring.sort();

  // Combine the arrays in the desired order
  return [...exactMatch, ...prefix, ...substring];
}

// Example usage:
const input = "ge";
