```javascript
function sortStrings(inputString, array) {
    // Helper function to determine the priority of a string
    function getPriority(str) {
        if (str === inputString) {
            return 1; // Exact match
        } else if (str.startsWith(inputString)) {
            return 2; // Prefix match
        } else if (str.includes(inputString)) {
            return 3; // Substring match
        } else {
            return 4; // No match
        }
    }

    // Sort the array based on the priority and alphabetical order
    array.sort((a, b) => {
        const priorityA = getPriority(a);
        const priorityB = getPriority(b);

        if (priorityA !== priorityB) {
            return priorityA - priorityB;
        } else {
            return a.localeCompare(b);
        }
    });

    return array;
}

// Example usage
const inputString = "ge";
const array = ["Algeria", "Argentina", "Germany", "Georgia"];
const sortedArray = sortStrings(inputString, array);
console.log(sortedArray); // Output: ["Georgia", "Germany", "Algeria", "Argentina"]
```

