            std::cout << element.getIntegerValue() << " ";
        } else if (element.getType() == PythonVariable::STRING) {
            std::cout << element.getStringValue() << " ";
        }
    }
    std::cout << std::endl;
    std::cout << "Map value: ";
    for (const auto& pair : mapVar.getMapValue()) {
