```cpp
#include <variant>
#include <string>
#include <vector>
#include <unordered_map>
#include <iostream>

using PyStyleVar = std::variant<int, std::string, std::vector<PyStyleVar>, std::unordered_map<std::string, PyStyleVar>>;

// Helper function to print PyStyleVar
void printPyStyleVar(const PyStyleVar& var) {
    std::visit([](const auto& value) {
        using T = std::decay_t<decltype(value)>;
        if constexpr (std::is_same_v<T, int>) {
            std::cout << value;
        } else if constexpr (std::is_same_v<T, std::string>) {
            std::cout << '"' << value << '"';
        } else if constexpr (std::is_same_v<T, std::vector<PyStyleVar>>) {
            std::cout << '[';
            for (size_t i = 0; i < value.size(); ++i) {
                printPyStyleVar(value[i]);
                if (i != value.size() - 1) {
                    std::cout << ", ";
                }
            }
            std::cout << ']';
        } else if constexpr (std::is_same_v<T, std::unordered_map<std::string, PyStyleVar>>) {
            std::cout << '{';
            bool first = true;
            for (const auto& [key, val] : value) {
                if (!first) {
                    std::cout << ", ";
                }
                first = false;
                std::cout << '"' << key << "\": ";
                printPyStyleVar(val);
            }
            std::cout << '}';
        }
    }, var);
}

int main() {
    PyStyleVar var = 42;
    printPyStyleVar(var); // Output: 42

    var = "Hello";
    printPyStyleVar(var); // Output: "Hello"

    var = std::vector<PyStyleVar>{1, 2, 3};
    printPyStyleVar(var); // Output: [1, 2, 3]

    var = std::unordered_map<std::string, PyStyleVar>{{"key1", 1}, {"key2", "value2"}};
    printPyStyleVar(var); // Output: {"key1": 1, "key2": "value2"}

    return 0;
}
```

This implementation uses `std::visit` to handle the different types of values in the `PyStyleVar`. The `printPyStyleVar` function demonstrates how to access and print the values stored in the `PyStyleVar`.
