```java
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;

public class AuthHelper {

    private static final String CLIENT_ID = "<your-client-id>";
    private static final String CLIENT_SECRET = "<your-client-secret>";
    private static final String AUTHORITY = "https://login.microsoftonline.com/<your-tenant-id>";
    private static final String REDIRECT_URI = "<your-redirect-uri>";
    private static final String SCOPE = "https://graph.microsoft.com/.default";

    public static String getUserAccessToken(String authorizationCode, String userCode) throws IOException, InterruptedException {
        // Step 1: Get a token for your app (client credentials)
        String clientCredentialsToken = getClientCredentialsToken();

        // Step 2: Request an authorization code from the user
        String authorizationCodeToken = getAuthorizationCodeToken(authorizationCode, clientCredentialsToken);

        // Step 3: Request an access token using the authorization code
        return getAccessToken(authorizationCodeToken, userCode);
    }

    private static String getClientCredentialsToken() throws IOException, InterruptedException {
        String tokenEndpoint = AUTHORITY + "/oauth2/v2.0/token";
        String clientIdSecret = CLIENT_ID + ":" + CLIENT_SECRET;
        String encodedClientIdSecret = Base64.getEncoder().encodeToString(clientIdSecret.getBytes());

        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(tokenEndpoint))
                .header("Content-Type", "application/x-www-form-urlencoded")
                .header("Authorization", "Basic " + encodedClientIdSecret)
                .POST(HttpRequest.BodyPublishers.ofString("grant_type=client_credentials&scope=" + SCOPE))
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        return parseTokenResponse(response.body());
    }

    private static String getAuthorizationCodeToken(String authorizationCode, String clientCredentialsToken) throws IOException, InterruptedException {
        String tokenEndpoint = AUTHORITY + "/oauth2/v2.0/token";

        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(tokenEndpoint))
                .header("Content-Type", "application/x-www-form-urlencoded")
                .POST(HttpRequest.BodyPublishers.ofString("grant_type=authorization_code&code=" + authorizationCode + "&redirect_uri=" + REDIRECT_URI + "&client_id=" + CLIENT_ID + "&client_secret=" + CLIENT_SECRET))
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        return parseTokenResponse(response.body());
    }

    private static String getAccessToken(String authorizationCodeToken, String userCode) throws IOException, InterruptedException {
        // Parse the authorization code token to get the user code and redirect URI
        String[] parts = authorizationCodeToken.split("&");
        String userCodePart = parts[0].split("=")[1];
        String redirectUriPart = parts[1].split("=")[1];

        // Check if the user code matches the one provided to the custodian
        if (!userCode.equals(userCodePart)) {
            throw new RuntimeException("User code mismatch");
        }

        // Use the authorization code token to request an access token
        String tokenEndpoint = AUTHORITY + "/oauth2/v2.0/token";
        String authorizationCodeTokenPart = authorizationCodeToken.split("&")[0];
        String authorizationCodeTokenValue = authorizationCodeTokenPart.split("=")[1];

        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(tokenEndpoint))
                .header("Content-Type", "application/x-www-form-urlencoded")
                .POST(HttpRequest.BodyPublishers.ofString("grant_type=authorization_code&code=" + authorizationCodeTokenValue + "&redirect_uri=" + redirectUriPart + "&client_id=" + CLIENT_ID + "&client_secret=" + CLIENT_SECRET))
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        return parseTokenResponse(response.body());
    }

    private static String parseTokenResponse(String responseBody) {
        Map<String, String> params = new HashMap<>();
        for (String param : responseBody.split("&")) {
            String[] keyValue = param.split("=");
            params.put(keyValue[0], keyValue[1]);
        }
        return params.get("access_token");
    }
}
