public class AuthHelper {

    private static final String CLIENT_ID = "<your-client-id>";
    private static final String CLIENT_SECRET = "<your-client-secret>";
    private static final String AUTHORITY = "https://login.microsoftonline.com/<your-tenant-id>";
    private static final String REDIRECT_URI = "<your-redirect-uri>";
    private static final String SCOPE = "https://graph.microsoft.com/.default";

    public static String getUserAccessToken(String authorizationCode, String userCode) throws IOException, InterruptedException {
        // Step 1: Get a token for your app (client credentials)
        String clientCredentialsToken = getClientCredentialsToken();

        // Step 2: Request an authorization code from the user
        String authorizationCodeToken = getAuthorizationCodeToken(authorizationCode, clientCredentialsToken);

        // Step 3: Request an access token using the authorization code
        return getAccessToken(authorizationCodeToken, userCode);
    }

    private static String getClientCredentialsToken() throws IOException, InterruptedException {
        String tokenEndpoint = AUTHORITY + "/oauth2/v2.0/token";
        String clientIdSecret = CLIENT_ID + ":" + CLIENT_SECRET;
        String encodedClientIdSecret = Base64.getEncoder().encodeToString(clientIdSecret.getBytes());

        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(tokenEndpoint))
                .header("Content-Type", "application/x-www-form-urlencoded")
                .header("Authorization", "Basic " + encodedClientIdSecret)
                .POST(HttpRequest.BodyPublishers.ofString("grant_type=client_credentials&scope=" + SCOPE))
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
