        String tokenEndpoint = AUTHORITY + "/oauth2/v2.0/token";

        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(tokenEndpoint))
                .header("Content-Type", "application/x-www-form-urlencoded")
                .POST(HttpRequest.BodyPublishers.ofString("grant_type=authorization_code&code=" + authorizationCode + "&redirect_uri=" + REDIRECT_URI + "&client_id=" + CLIENT_ID + "&client_secret=" + CLIENT_SECRET))
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        return parseTokenResponse(response.body());
    }

    private static String getAccessToken(String authorizationCodeToken, String userCode) throws IOException, InterruptedException {
        // Parse the authorization code token to get the user code and redirect URI
        String[] parts = authorizationCodeToken.split("&");
        String userCodePart = parts[0].split("=")[1];
        String redirectUriPart = parts[1].split("=")[1];

        // Check if the user code matches the one provided to the custodian
        if (!userCode.equals(userCodePart)) {
            throw new RuntimeException("User code mismatch");
        }

        // Use the authorization code token to request an access token
        String tokenEndpoint = AUTHORITY + "/oauth2/v2.0/token";
        String authorizationCodeTokenPart = authorizationCodeToken.split("&")[0];
        String authorizationCodeTokenValue = authorizationCodeTokenPart.split("=")[1];

        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(tokenEndpoint))
                .header("Content-Type", "application/x-www-form-urlencoded")
                .POST(HttpRequest.BodyPublishers.ofString("grant_type=authorization_code&code=" + authorizationCodeTokenValue + "&redirect_uri=" + redirectUriPart + "&client_id=" + CLIENT_ID + "&client_secret=" + CLIENT_SECRET))
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        return parseTokenResponse(response.body());
    }

    private static String parseTokenResponse(String responseBody) {
        Map<String, String> params = new HashMap<>();
        for (String param : responseBody.split("&")) {
            String[] keyValue = param.split("=");
            params.put(keyValue[0], keyValue[1]);
        }
        return params.get("access_token");
